 static final BlockPos FROM=new BlockPos(40,16,-27),TO=new BlockPos(43,19,-24),CENTER=MineAccessRuntime.ROOT;
 static void run(GameTestHelper h)throws Exception{var level=h.getLevel();var server=level.getServer();server.tickRateManager().setTickRate(20);var mine=ConstructionService.store(server).projects().stream().filter(q->q.blueprint().toString().equals(Profession.MINER.buildingId())).findFirst().orElseThrow();var p=server.getPlayerList().getPlayer(mine.owner());h.assertTrue(p!=null,"Original earned Miner attends");server.getPlayerList().deop(p.getGameProfile());var store=CommerceService.store(server);var track=store.professions(p.getUUID()).track(Profession.MINER);var route=MineAccessSavedData.get(server).evidence().route(p.getUUID()).orElseThrow();for(long cell:route.cells())level.getChunkAt(BlockPos.of(cell));for(var pos:BlockPos.betweenClosed(FROM.offset(-8,-3,-8),TO.offset(2,3,2)))level.getChunkAt(pos);MineAccessRuntime.teleport(p,.1);var admin=ClaimRuntimeTests.vanillaPlayer(level,UUID.nameUUIDFromBytes("ExcavationWarden".getBytes(java.nio.charset.StandardCharsets.UTF_8)),"DigWarden");server.getPlayerList().op(admin.getGameProfile());admin.setGameMode(GameType.CREATIVE);admin.teleportTo(level,38.5,17,-25.5,Set.of(),0,0);level.getChunkSource().move(admin);
  if(track.completedQuestIds().contains(MineExcavation.FINAL)){h.assertTrue(server.getCommands().getDispatcher().execute("kingdom admin profession excavation_status "+p.getGameProfile().getName(),server.createCommandSourceStack())==1,"Actual operator console reads archived authorization status");boolean ordinaryStatus=false;try{server.getCommands().getDispatcher().execute("kingdom admin profession excavation_status "+p.getGameProfile().getName(),p.createCommandSourceStack());}catch(com.mojang.brigadier.exceptions.CommandSyntaxException expected){ordinaryStatus=true;}h.assertTrue(ordinaryStatus,"Ordinary player cannot invoke operator excavation diagnostics");h.assertTrue(track.xp()==4800&&track.completedQuestIds().size()==24&&store.professions(p.getUUID()).rank(Profession.MINER,ProfessionQuestService.catalog())==ProfessionRank.MASTER&&ConstructionService.structureIntact(level,mine),"Third JVM restores all24real proofs/4800XP/Master/original Mine-Doran");h.assertTrue(store.mineExcavation(p.getUUID()).isPresent()&&store.professionInspectionEvidence(p.getUUID(),MineExcavation.PROJECT).isPresent()&&store.professionInspectionEvidence(p.getUUID(),MineExcavation.FINAL).isPresent(),"Archived canonical authorization and both confirmed audits restore");MineExcavation.completedSnapshot(admin,p,MineExcavation.FINAL,CENTER);CommerceService.verifyReceipt(p);server.getPlayerList().deop(admin.getGameProfile());com.mojang.logging.LogUtils.getLogger().info("MINE_EXCAVATION_RESTART_PASSED: real all24earned4800XP/Master/archived prior authorization/current excavation-access/old native source proofs/audits/receipt/Mine-Doran restored; no Master item minted");h.succeed();return;}
  h.assertTrue(track.xp()==4200&&track.completedQuestIds().size()==22,"Actual22native source proofs only before final two assessments");if(store.mineExcavation(p.getUUID()).isPresent()){finish(h,p,admin);return;}
  for(var cursor:BlockPos.betweenClosed(new BlockPos(33,15,-32),new BlockPos(43,15,-23))){var pos=cursor.immutable();if(level.getBlockState(pos).isAir())level.setBlock(pos,Blocks.STONE.defaultBlockState(),3);}for(int x=34;x<=39;x++){var pos=new BlockPos(x,16,-32);h.assertTrue(level.getBlockState(pos).isAir(),"Controlled private bridge cells are empty");level.setBlock(pos,Blocks.STONE.defaultBlockState(),3);}for(var cursor:BlockPos.betweenClosed(FROM,TO)){var pos=cursor.immutable();h.assertTrue(level.getBlockState(pos).isAir(),"Controlled approved non-NAT digging fixture only occupies empty cells");level.setBlock(pos,Blocks.STONE.defaultBlockState(),3);}
  boolean ordinary=false;try{server.getCommands().getDispatcher().execute("kingdom admin profession excavation "+p.getGameProfile().getName()+" 40 16 -27 43 19 -24 Owner consent and protected margin inspected",p.createCommandSourceStack());}catch(com.mojang.brigadier.exceptions.CommandSyntaxException expected){ordinary=true;}h.assertTrue(ordinary&&store.mineExcavation(p.getUUID()).isEmpty(),"Ordinary player cannot create an authorization through real command dispatcher");
  var nonce=MineExcavation.review(admin,p,FROM,TO,"Owner consent for controlled excavation and protected surroundings");level.setBlock(FROM,Blocks.DIRT.defaultBlockState(),3);boolean changed=false;try{MineExcavation.confirm(admin,nonce);}catch(IllegalStateException expected){changed=true;}h.assertTrue(changed&&store.mineExcavation(p.getUUID()).isEmpty(),"Changed preauthorization geometry refuses without recording authority");level.setBlock(FROM,Blocks.STONE.defaultBlockState(),3);nonce=MineExcavation.review(admin,p,FROM,TO,"Owner consent and unchanged surroundings before native excavation");ClaimRuntimeTests.ftbUnclaim(level,FROM);ClaimRuntimeTests.ftbClaim(admin,FROM);boolean denied=false;try{MineExcavation.confirm(admin,nonce);}catch(IllegalStateException expected){denied=true;}h.assertTrue(denied&&store.mineExcavation(p.getUUID()).isEmpty(),"Current FTB revocation refuses prior authority");ClaimRuntimeTests.ftbUnclaim(level,FROM);ClaimRuntimeTests.ftbClaim(p,FROM);
  int result=server.getCommands().getDispatcher().execute("kingdom admin profession excavation "+p.getGameProfile().getName()+" 40 16 -27 43 19 -24 Owner consent and safe protected surroundings before work",admin.createCommandSourceStack());h.assertTrue(result==1,"Real OP2command reviews original solid site with clickable confirmation");nonce=MineExcavation.currentReview(admin).orElseThrow();var dataRoot=server.getWorldPath(LevelResource.ROOT).resolve("data");var failing=faultedRoot(dataRoot);var cache=CommerceService.class.getDeclaredField("STORES");cache.setAccessible(true);((Map)cache.get(null)).put(server,failing);int confirmation=server.getCommands().getDispatcher().execute("kingdom admin profession confirm_excavation "+nonce,admin.createCommandSourceStack());h.assertTrue(confirmation==0,"Intentional after-rename failure reports uncertainty, never free XP");CommerceService.initialize(server);store=CommerceService.store(server);h.assertTrue(store.mineExcavation(p.getUUID()).orElseThrow().id().equals(nonce)&&store.professions(p.getUUID()).track(Profession.MINER).xp()==4200,"Actual committed prior authorization recovers after uncertain IO result with unchanged earned XP");for(var pos:BlockPos.betweenClosed(FROM,TO))h.assertTrue(level.getBlockState(pos).is(Blocks.STONE),"Authorization performs no automatic block destruction");CommerceService.verifyReceipt(p);com.mojang.logging.LogUtils.getLogger().info("MINE_EXCAVATION_PENDING_PASSED: actual OP2onsite prior authorization/current FTB and geometry refusals/ordinary dispatcher denial/real after-rename IO recovery,64controlled stone cells unchanged/no XP or permission grant; first JVM saves canonical authority");h.succeed();
 }
 /** Test-only IO injection keeps the production writer package-private and avoids split JPMS packages. */
 static EconomyStore faultedRoot(Path root)throws Exception{var writer=Class.forName(EconomyStore.class.getName()+"$Writer");var proxy=java.lang.reflect.Proxy.newProxyInstance(EconomyStore.class.getClassLoader(),new Class<?>[]{writer},(object,method,args)->{if(method.getName().equals("write")){AtomicNbt.write((Path)args[0],(net.minecraft.nbt.CompoundTag)args[1]);throw new java.io.IOException("Private after-rename authorization fault");}throw new UnsupportedOperationException("Test writer supports writes only");});var open=EconomyStore.class.getDeclaredMethod("open",Path.class,writer);open.setAccessible(true);return (EconomyStore)open.invoke(null,root,proxy);}
 static void finish(GameTestHelper h,ServerPlayer p,ServerPlayer admin)throws Exception{var server=p.server;var level=p.serverLevel();var store=CommerceService.store(server);h.assertTrue(store.mineExcavation(p.getUUID()).orElseThrow().volume()==64,"Second JVM restores real prior64cell authorization");for(int y=TO.getY();y>=FROM.getY();y--)for(int x=FROM.getX();x<=TO.getX();x++)for(int z=FROM.getZ();z<=TO.getZ();z++){var pos=new BlockPos(x,y,z);h.assertTrue(level.getBlockState(pos).is(Blocks.STONE),"No retrospective hole substituted for approved solid target");BlacksmithRepairRuntime.near(p,pos);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.DIAMOND_PICKAXE));h.assertTrue(p.gameMode.destroyBlock(pos)&&level.getBlockState(pos).isAir(),"Real native permitted player excavation, not server automatic clearing");}MineAccessRuntime.teleport(p,.1);var review=ProfessionInspectionService.review(admin,p,MineExcavation.PROJECT,CENTER,"Original prior authorization fulfilled with protected margin and safe access");var margin=TO.east();var old=level.getBlockState(margin);level.setBlock(margin,Blocks.STONE.defaultBlockState(),3);boolean stale=false;try{ProfessionInspectionService.confirm(admin,review);}catch(IllegalStateException expected){stale=true;}h.assertTrue(stale&&store.professions(p.getUUID()).track(Profession.MINER).xp()==4200,"Changing protected surroundings after review refuses XP");level.setBlock(margin,old,3);review=ProfessionInspectionService.review(admin,p,MineExcavation.PROJECT,CENTER,"Current preserved surroundings and original player mine access inspected");ClaimRuntimeTests.opacUnclaim(level,FROM);ClaimRuntimeTests.opacClaim(level,admin.getUUID(),FROM);boolean denied=false;try{ProfessionInspectionService.confirm(admin,review);}catch(IllegalStateException expected){denied=true;}h.assertTrue(denied,"Independent OPAC revocation refuses completed excavation inspection");ClaimRuntimeTests.opacUnclaim(level,FROM);ClaimRuntimeTests.opacClaim(level,p.getUUID(),FROM);review=ProfessionInspectionService.review(admin,p,MineExcavation.PROJECT,CENTER,"Authorized excavation preserved surroundings connected safe access verified");ProfessionInspectionService.confirm(admin,review);h.assertTrue(store.professions(p.getUUID()).track(Profession.MINER).xp()==4500,"Completed real excavation earns300XPonce");review=ProfessionInspectionService.review(admin,p,MineExcavation.FINAL,CENTER,"Actual geology safety specimen valuable extraction and Nether records inspected");ProfessionInspectionService.confirm(admin,review);h.assertTrue(store.professions(p.getUUID()).track(Profession.MINER).xp()==4800&&store.professions(p.getUUID()).track(Profession.MINER).completedQuestIds().size()==24&&store.professions(p.getUUID()).rank(Profession.MINER,ProfessionQuestService.catalog())==ProfessionRank.MASTER,"Every8A8J8Mreal objective earns4800XP/Master purchase rights, no item minted");boolean replay=false;try{ProfessionInspectionService.review(admin,p,MineExcavation.FINAL,CENTER,"Repeated final assessment must never award again");}catch(IllegalStateException expected){replay=true;}h.assertTrue(replay,"Final reward cannot repeat");CommerceService.verifyReceipt(p);store.archive(admin.getUUID(),"Private full Miner authorization and inspection continuity");var reopened=EconomyStore.open(server.getWorldPath(LevelResource.ROOT).resolve("data"));h.assertTrue(reopened.mineExcavation(p.getUUID()).equals(store.mineExcavation(p.getUUID()))&&reopened.professions(p.getUUID()).equals(store.professions(p.getUUID())),"Canonical authorization/old role records/audits reopen through archive");server.getPlayerList().deop(admin.getGameProfile());com.mojang.logging.LogUtils.getLogger().info("MINE_EXCAVATION_NATIVE_PASSED: restored prior actual authority/native64player breaks/retained safe connected access/lights/tool/sorting/plan, stale protected margin/current OPAC/replay refusal, confirmed final geology and real native expedition records/all24earned4800XP/Master/archive reopen; only controlled private stone terrain/raw tools and old service5to1, no source/quest/count/XP/rank injection or Master item mint");h.succeed();}
